input.command:
cargo add windows-sys --features Win32_Foundation,Win32_UI_WindowsAndMessaging 2>&1 | tail -3
mkdir -p .cargo && cat > .cargo/config.toml <<'EOF'
[build]
target = "x86_64-pc-windows-gnu"

[target.x86_64-pc-windows-gnu]
# MinGW-w64 cross linker (Debian/Ubuntu: `apt install gcc-mingw-w64-x86-64`)
linker = "x86_64-w64-mingw32-gcc"
ar = "x86_64-w64-mingw32-ar"
EOF
cat > src/main.rs <<'EOF'
use windows_sys::Win32::UI::WindowsAndMessaging::{MB_ICONINFORMATION, MB_OK, MessageBoxW};

fn wide(s: &str) -> Vec<u16> {
    s.encode_utf16().chain(std::iter::once(0)).collect()
}

fn main() {
    let text = wide("Hello from Rust (x86_64-pc-windows-gnu)!");
    let caption = wide("win-app");
    unsafe {
        MessageBoxW(
            std::ptr::null_mut(),
            text.as_ptr(),
            caption.as_ptr(),
            MB_OK | MB_ICONINFORMATION,
        );
    }
}
EOF
cat > rust-toolchain.toml <<'EOF'
[toolchain]
channel = "stable"
targets = ["x86_64-pc-windows-gnu"]
EOF
cargo build 2>&1 | tail -15

